import crypto from 'node:crypto';
import { buildZip } from './zip.js';

const sha = (b) => crypto.createHash('sha256').update(b).digest('hex');
export const MANIFEST_SHA = sha('manifest');

// Rendered by the server's RenderTemplateBundle from its domain test manifest (Go archive/zip: stored entries with data
// descriptors and extended timestamps).
export const GO_BUNDLE = Buffer.from('', 'base64');

// A bundle shaped like the server's; files maps path -> content, index overrides bundle.json fields.
export function templateBundle({ inject = '# Demo\n\nHelp with demos.\n', files = {}, index = {}, unlisted = {} } = {}) {
  const all = { 'inject.md': inject, 'connectors.json': '[]', 'customizations.json': '{}', 'sop/triage.md': '# Triage\n', ...files };
  for (const [k, v] of Object.entries(all)) if (v === null) delete all[k];
  const paths = Object.keys(all).sort();
  const listing = paths.map((p) => ({ path: p, sha256: sha(all[p]), size: Buffer.byteLength(all[p]) }));
  const ix = { files: listing, manifest_sha256: MANIFEST_SHA, render_version: 1, template: 'demo', version: '1.0.0', ...index };
  const entries = [['bundle.json', JSON.stringify(ix)], ...paths.map((p) => [p, all[p]]), ...Object.entries(unlisted)];
  const zip = buildZip(entries.map(([name, data]) => ({ name, data, descriptor: true, flags: 8 })));
  return { zip, sha: sha(zip), size: zip.length };
}
